/// Length of the SQL text in `query`, excluding the trailing NUL terminator.
fn sql_len(query: &Bytes) -> usize {
    debug_assert_eq!(query.last(), Some(&0));
    query.len().saturating_sub(1)
}

/// Prepare the next statement from `query` (SQL text followed by a NUL terminator),
/// advancing `query` past the consumed SQL.
///
/// When `nByte` does not cover a NUL terminator, SQLite makes a private copy of the *entire*
/// remaining input on every call to `sqlite3_prepare_v3()`, which made executing a string of
/// N statements O(N^2). Passing the terminator lets SQLite parse the buffer in place.
fn prepare(
    conn: *mut sqlite3,
    query: &mut Bytes,
    persistent: bool,
) -> Result<Option<StatementHandle>, Error> {
    let mut flags = 0;

    // For some reason, when building with the `sqlcipher` feature enabled
    // `SQLITE_PREPARE_PERSISTENT` ends up being `i32` instead of `u32`. Crazy, right?
    #[allow(trivial_casts, clippy::unnecessary_cast)]
    if persistent {
        // SQLITE_PREPARE_PERSISTENT
        //  The SQLITE_PREPARE_PERSISTENT flag is a hint to the query
        //  planner that the prepared statement will be retained for a long time
        //  and probably reused many times.
        flags |= SQLITE_PREPARE_PERSISTENT as u32;
